## Summary
Fixed `Interval.fromISO` in `/luxon/src/interval.js` so it works when `Settings.throwOnInvalid === true`, by wrapping the two `DateTime.fromISO` parses in try/catch and branching on boolean validity flags instead of `start.isValid`/`end.isValid`. The final `Interval.invalid("unparsable", ...)` line is unchanged. No other file touched.

## Final source of `fromISO` (src/interval.js, lines 134–170)
```js
  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (e) {
        startIsValid = false;
      }

      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (e) {
        endIsValid = false;
      }

      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }

      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed asISO 8601`);
  }
```

