const { Duration } = require("/luxon/src/luxon.js");

const units = [
  "years",
  "quarters",
  "months",
  "weeks",
  "days",
  "hours",
  "minutes",
  "seconds",
  "milliseconds"
];

let pass = 0,
  fail = 0;
const failures = [];

for (const conversionAccuracy of ["casual", "longterm"]) {
  for (let i = 0; i < units.length; i++) {
    for (let j = i + 1; j < units.length; j++) {
      const big = units[i],
        small = units[j];
      const label = `${conversionAccuracy} ${big}->${small}`;
      const problems = [];

      const smallToBig = Duration.fromObject({ [small]: 1 }, { conversionAccuracy })
        .shiftTo(big)
        .get(big);
      if (!(Number.isFinite(smallToBig) && smallToBig > 0)) {
        problems.push(`{${small}:1}.shiftTo(${big}).${big} = ${smallToBig}`);
      }

      const bigToSmall = Duration.fromObject({ [big]: 1 }, { conversionAccuracy })
        .shiftTo(small)
        .get(small);
      if (!(Number.isFinite(bigToSmall) && bigToSmall > 0)) {
        problems.push(`{${big}:1}.shiftTo(${small}).${small} = ${bigToSmall}`);
      }

      const norm = Duration.fromObject({ [big]: 1, [small]: 1 }, { conversionAccuracy })
        .normalize()
        .toObject();
      if (Object.values(norm).some((v) => Number.isNaN(v))) {
        problems.push(`normalize({${big}:1,${small}:1}) = ${JSON.stringify(norm)}`);
      }

      if (problems.length === 0) {
        pass++;
        console.log(`PASS ${label}`);
      } else {
        fail++;
        failures.push(`${label}: ${problems.join("; ")}`);
        console.log(`FAIL ${label}: ${problems.join("; ")}`);
      }
    }
  }
}

console.log(`\nTOTAL: ${pass} PASS, ${fail} FAIL (of ${pass + fail})`);
if (failures.length) {
  console.log("FAILURES:");
  failures.forEach((f) => console.log("  " + f));
}
EOF
